1	package com.cc91.service;
2	
3	import com.cc91.dto.LoginRequest;
4	import com.cc91.dto.LoginResponse;
5	import com.cc91.dto.RefreshTokenRequest;
6	import com.cc91.dto.RefreshTokenResponse;
7	import com.cc91.dto.RegisterRequest;
8	import com.cc91.dto.RegisterResponse;
9	import com.cc91.dto.VerifyEmailRequest;
10	import com.cc91.entity.RefreshToken;
11	import com.cc91.entity.User;
12	import com.cc91.entity.VerificationCode;
13	import com.cc91.exception.BadRequestException;
14	import com.cc91.exception.ResourceNotFoundException;
15	import com.cc91.exception.UnauthorizedException;
16	import com.cc91.repository.RefreshTokenRepository;
17	import com.cc91.repository.UserRepository;
18	import com.cc91.repository.VerificationCodeRepository;
19	import com.cc91.security.JwtUtil;
20	import org.slf4j.Logger;
21	import org.slf4j.LoggerFactory;
22	import org.springframework.beans.factory.annotation.Value;
23	import org.springframework.security.authentication.AuthenticationManager;
24	import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
25	import org.springframework.security.core.AuthenticationException;
26	import org.springframework.security.crypto.password.PasswordEncoder;
27	import org.springframework.stereotype.Service;
28	import org.springframework.transaction.annotation.Transactional;
29	
30	import java.security.SecureRandom;
31	import java.time.Duration;
32	import java.time.LocalDateTime;
33	import java.util.List;
34	import java.util.UUID;
35	
36	@Service
37	public class AuthService {
38	
39	    // Keep response messages centralized so controllers and tests can assert stable
40	    // API behavior.
41	    public static final String USERNAME_ALREADY_USED = "Username already exists";
42	    public static final String EMAIL_ALREADY_REGISTERED = "Email already registered";
43	    public static final String VERIFICATION_CODE_SENT = "Verification code sent";
44	    public static final String VERIFICATION_CODE_NOT_FOUND = "Verification code not found";
45	    public static final String VERIFICATION_CODE_USED = "Verification code already used";
46	    public static final String VERIFICATION_CODE_EXPIRED = "Verification code expired";
47	    public static final String VERIFICATION_CODE_TYPE_INVALID = "Verification code type invalid";
48	    public static final String USER_NOT_FOUND = "User not found";
49	    public static final String BAD_CREDENTIALS = "Invalid username or password";
50	    public static final String EMAIL_NOT_VERIFIED = "Please verify your email first";
51	    public static final String ACCOUNT_LOCKED_PREFIX = "Account locked, try again in ";
52	    public static final String ACCOUNT_UNAVAILABLE = "Account unavailable, please log in again";
53	    public static final String REFRESH_TOKEN_INVALID = "Refresh token invalid";
54	    public static final String REFRESH_TOKEN_EXPIRED_OR_REVOKED = "Refresh token expired or revoked";
55	
56	    private static final Logger logger = LoggerFactory.getLogger(AuthService.class);
57	    private static final String REGISTER_CODE_TYPE = "REGISTER";
58	    private static final String PASSWORD_RESET_CODE_TYPE = "PASSWORD_RESET";
59	    private static final int VERIFICATION_CODE_EXPIRES_IN_SECONDS = 600;
60	
61	    private final UserRepository userRepository;
62	    private final VerificationCodeRepository verificationCodeRepository;
63	    private final RefreshTokenRepository refreshTokenRepository;
64	    private final PasswordEncoder passwordEncoder;
65	    private final JwtUtil jwtUtil;
66	    private final AuthenticationManager authenticationManager;
67	    private final SecureRandom secureRandom = new SecureRandom();
68	
69	    @Value("${account.lock.max-attempts:5}")
70	    private int maxFailedAttempts;
71	
72	    @Value("${account.lock.duration-seconds:30}")
73	    private int lockDurationSeconds;
74	
75	    @Value("${jwt.refresh-expiration:604800000}")
76	    private Long refreshExpiration;
77	
78	    public AuthService(
79	            UserRepository userRepository,
80	            VerificationCodeRepository verificationCodeRepository,
81	            RefreshTokenRepository refreshTokenRepository,
82	            PasswordEncoder passwordEncoder,
83	            JwtUtil jwtUtil,
84	            AuthenticationManager authenticationManager) {
85	        this.userRepository = userRepository;
86	        this.verificationCodeRepository = verificationCodeRepository;
87	        this.refreshTokenRepository = refreshTokenRepository;
88	        this.passwordEncoder = passwordEncoder;
89	        this.jwtUtil = jwtUtil;
90	        this.authenticationManager = authenticationManager;
91	    }
92	
93	    @Transactional
94	    public RegisterResponse register(RegisterRequest request) {
95	        // Registration reserves username and email immediately, but keeps the account
96	        // locked
97	        // until the user proves ownership of the email verification code.
98	        if (userRepository.existsByUsername(request.getUsername())) {
99	            throw new BadRequestException(USERNAME_ALREADY_USED);
100	        }
101	        if (userRepository.existsByEmail(request.getEmail())) {
102	            throw new BadRequestException(EMAIL_ALREADY_REGISTERED);
103	        }
104	
105	        User user = new User(
106	                request.getUsername(),
107	                request.getEmail(),
108	                passwordEncoder.encode(request.getPassword()));
109	        user.setIsLocked(true);
110	        user.setLockUntil(null);
111	        userRepository.save(user);
112	
113	        String code = generateVerificationCode();
114	        LocalDateTime expiresAt = LocalDateTime.now().plusSeconds(VERIFICATION_CODE_EXPIRES_IN_SECONDS);
115	        verificationCodeRepository.save(new VerificationCode(request.getEmail(), code, REGISTER_CODE_TYPE, expiresAt));
116	
117	        logger.info("Register verification code for {}: {}, expiresAt={}", request.getEmail(), code, expiresAt);
118	        return new RegisterResponse(VERIFICATION_CODE_SENT, VERIFICATION_CODE_EXPIRES_IN_SECONDS);
119	    }
120	
121	    @Transactional
122	    public void verifyEmail(VerifyEmailRequest request) {
123	        // A valid one-time registration code is the only path that unlocks a new
124	        // account.
125	        VerificationCode verificationCode = verificationCodeRepository
126	                .findByEmailAndCodeAndType(request.getEmail(), request.getCode(), REGISTER_CODE_TYPE)
127	                .orElseThrow(() -> new BadRequestException(VERIFICATION_CODE_NOT_FOUND));
128	
129	        validateVerificationCode(verificationCode);
130	
131	        User user = userRepository.findByEmail(request.getEmail())
132	                .orElseThrow(() -> new ResourceNotFoundException(USER_NOT_FOUND));
133	
134	        verificationCode.setUsed(true);
135	        verificationCodeRepository.save(verificationCode);
136	
137	        user.setIsLocked(false);
138	        user.setLockUntil(null);
139	        user.setFailedLoginAttempts(0);
140	        userRepository.save(user);
141	
142	        logger.info("Email verified and account enabled: {}", request.getEmail());
143	    }
144	
145	    @Transactional(noRollbackFor = UnauthorizedException.class)
146	    public LoginResponse login(LoginRequest request) {
147	        // Spring Security performs the password check; this service records lockout
148	        // state
149	        // around that check and creates the stateless session tokens after success.
150	        User user = userRepository.findByUsername(request.getUsername())
151	                .orElseThrow(() -> new UnauthorizedException(BAD_CREDENTIALS));
152	
153	        ensureUserCanAttemptLogin(user);
154	
155	        try {
156	            authenticationManager.authenticate(
157	                    new UsernamePasswordAuthenticationToken(request.getUsername(), request.getPassword()));
158	        } catch (AuthenticationException e) {
159	            boolean locked = recordFailedLogin(user);
160	            if (locked) {
161	                throw new UnauthorizedException(ACCOUNT_LOCKED_PREFIX + lockDurationSeconds + " second(s)");
162	            }
163	            throw new UnauthorizedException(BAD_CREDENTIALS);
164	        }
165	
166	        resetFailedLoginState(user);
167	
168	        String accessToken = jwtUtil.generateToken(user.getUsername());
169	        RefreshToken refreshToken = createRefreshToken(user.getId());
170	
171	        logger.info("User logged in: {}", user.getUsername());
172	        return new LoginResponse(
173	                accessToken,
174	                refreshToken.getToken(),
175	                jwtUtil.getExpiration(),
176	                user.getUsername(),
177	                user.getEmail(),
178	                user.getRole());
179	    }
180	
181	    private void ensureUserCanAttemptLogin(User user) {
182	        // isLocked with null lockUntil means "email not verified"; with a future
183	        // lockUntil
184	        // means temporary lock caused by repeated failed login attempts.
185	        if (!Boolean.TRUE.equals(user.getIsLocked())) {
186	            return;
187	        }
188	
189	        if (user.getLockUntil() == null) {
190	            throw new UnauthorizedException(EMAIL_NOT_VERIFIED);
191	        }
192	
193	        if (LocalDateTime.now().isBefore(user.getLockUntil())) {
194	            long remainingSeconds = Duration.between(LocalDateTime.now(), user.getLockUntil()).toSeconds();
195	            throw new UnauthorizedException(ACCOUNT_LOCKED_PREFIX + Math.max(1, remainingSeconds) + " second(s)");
196	        }
197	
198	        user.setIsLocked(false);
199	        user.setLockUntil(null);
200	        user.setFailedLoginAttempts(0);
201	        userRepository.save(user);
202	    }
203	
204	    private boolean recordFailedLogin(User user) {
205	        // Failed attempts are stored on the user record so protection survives restarts
206	        // and applies consistently across all application instances.
207	        int attempts = user.getFailedLoginAttempts() == null ? 1 : user.getFailedLoginAttempts() + 1;
208	        user.setFailedLoginAttempts(attempts);
209	
210	        boolean locked = false;
211	        if (attempts >= maxFailedAttempts) {
212	            user.setIsLocked(true);
213	            user.setLockUntil(LocalDateTime.now().plusSeconds(lockDurationSeconds));
214	            locked = true;
215	            logger.warn("Account locked after failed login attempts: username={}, attempts={}", user.getUsername(),
216	                    attempts);
217	        }
218	
219	        userRepository.save(user);
220	        logger.warn("Login failed: username={}, attempts={}", user.getUsername(), attempts);
221	        return locked;
222	    }
223	
224	    private void resetFailedLoginState(User user) {
225	        if (user.getFailedLoginAttempts() == null || user.getFailedLoginAttempts() == 0) {
226	            return;
227	        }
228	
229	        user.setFailedLoginAttempts(0);
230	        user.setIsLocked(false);
231	        user.setLockUntil(null);
232	        userRepository.save(user);
233	    }
234	
235	    private String generateVerificationCode() {
236	        int code = 100000 + secureRandom.nextInt(900000);
237	        return String.valueOf(code);
238	    }
239	
240	    @Transactional
241	    public RefreshToken createRefreshToken(Long userId) {
242	        RefreshToken refreshToken = new RefreshToken(
243	                userId,
244	                UUID.randomUUID().toString(),
245	                LocalDateTime.now().plusSeconds(refreshExpiration / 1000));
246	        return refreshTokenRepository.save(refreshToken);
247	    }
248	
249	    @Transactional
250	    public RefreshTokenResponse refreshToken(RefreshTokenRequest request) {
251	        // Refresh tokens are rotated on every use. The old token is revoked before a
252	        // new
253	        // token pair is returned, reducing the value of a leaked refresh token.
254	        RefreshToken refreshToken = refreshTokenRepository.findByToken(request.getRefreshToken())
255	                .orElseThrow(() -> new UnauthorizedException(REFRESH_TOKEN_INVALID));
256	
257	        if (!refreshToken.isValid()) {
258	            throw new UnauthorizedException(REFRESH_TOKEN_EXPIRED_OR_REVOKED);
259	        }
260	
261	        User user = userRepository.findById(refreshToken.getUserId())
262	                .orElseThrow(() -> new ResourceNotFoundException(USER_NOT_FOUND));
263	        if (Boolean.TRUE.equals(user.getIsLocked())) {
264	            throw new UnauthorizedException(ACCOUNT_UNAVAILABLE);
265	        }
266	
267	        refreshToken.setRevoked(true);
268	        refreshTokenRepository.save(refreshToken);
269	
270	        String newAccessToken = jwtUtil.generateToken(user.getUsername());
271	        RefreshToken newRefreshToken = createRefreshToken(user.getId());
272	
273	        logger.info("Token refreshed: {}", user.getUsername());
274	        return new RefreshTokenResponse(newAccessToken, newRefreshToken.getToken(), jwtUtil.getExpiration());
275	    }
276	
277	    @Transactional
278	    public void logout(String refreshToken) {
279	        // Logout only needs the refresh token because access tokens are short-lived
280	        // JWTs
281	        // and are not stored server-side.
282	        RefreshToken token = refreshTokenRepository.findByToken(refreshToken)
283	                .orElseThrow(() -> new UnauthorizedException(REFRESH_TOKEN_INVALID));
284	
285	        token.setRevoked(true);
286	        refreshTokenRepository.save(token);
287	
288	        logger.info("User logged out: userId={}", token.getUserId());
289	    }
290	
291	    @Transactional
292	    public void revokeAllUserTokens(Long userId) {
293	        List<RefreshToken> tokens = refreshTokenRepository.findByUserIdAndRevokedFalse(userId);
294	        tokens.forEach(token -> token.setRevoked(true));
295	        refreshTokenRepository.saveAll(tokens);
296	        logger.info("Revoked all refresh tokens for userId={}", userId);
297	    }
298	
299	    @Transactional
300	    public void forgotPassword(String email) {
301	        // Return the same public response whether the email exists or not to avoid
302	        // leaking which addresses are registered.
303	        if (!userRepository.existsByEmail(email)) {
304	            logger.warn("Password reset requested for unknown email: {}", email);
305	            return;
306	        }
307	
308	        String code = generateVerificationCode();
309	        LocalDateTime expiresAt = LocalDateTime.now().plusSeconds(VERIFICATION_CODE_EXPIRES_IN_SECONDS);
310	        verificationCodeRepository.save(new VerificationCode(email, code, PASSWORD_RESET_CODE_TYPE, expiresAt));
311	
312	        logger.info("Password reset verification code for {}: {}, expiresAt={}", email, code, expiresAt);
313	    }
314	
315	    @Transactional
316	    public void resetPassword(String email, String code, String newPassword) {
317	        // Password reset consumes a dedicated verification code and revokes existing
318	        // sessions so old refresh tokens cannot survive a credential change.
319	        VerificationCode verificationCode = verificationCodeRepository
320	                .findByEmailAndCode(email, code)
321	                .orElseThrow(() -> new BadRequestException(VERIFICATION_CODE_NOT_FOUND));
322	
323	        validateVerificationCode(verificationCode);
324	        if (!PASSWORD_RESET_CODE_TYPE.equals(verificationCode.getType())) {
325	            throw new BadRequestException(VERIFICATION_CODE_TYPE_INVALID);
326	        }
327	
328	        User user = userRepository.findByEmail(email)
329	                .orElseThrow(() -> new ResourceNotFoundException(USER_NOT_FOUND));
330	
331	        user.setPasswordHash(passwordEncoder.encode(newPassword));
332	        user.setFailedLoginAttempts(0);
333	        user.setIsLocked(false);
334	        user.setLockUntil(null);
335	        userRepository.save(user);
336	
337	        verificationCode.setUsed(true);
338	        verificationCodeRepository.save(verificationCode);
339	
340	        revokeAllUserTokens(user.getId());
341	        logger.info("Password reset completed: {}", email);
342	    }
343	
