79	    public AuthService(
80	            UserRepository userRepository,
81	            VerificationCodeRepository verificationCodeRepository,
82	            RefreshTokenRepository refreshTokenRepository,
83	            PasswordEncoder passwordEncoder,
84	            JwtUtil jwtUtil,
85	            AuthenticationManager authenticationManager,
86	            EmailService emailService) {
