96	    @Transactional
97	    public RegisterResponse register(RegisterRequest request) {
98	        // Registration reserves username and email immediately, but keeps the account
99	        // locked
100	        // until the user proves ownership of the email verification code.
101	        if (userRepository.existsByUsername(request.getUsername())) {
102	            throw new BadRequestException(USERNAME_ALREADY_USED);
