105	            throw new BadRequestException(EMAIL_ALREADY_REGISTERED);
106	        }
107	
108	        User user = new User(
109	                request.getUsername(),
110	                request.getEmail(),
111	                passwordEncoder.encode(request.getPassword()));
112	        user.setIsLocked(true);
113	        user.setLockUntil(null);
114	        userRepository.save(user);
115	
116	        String code = generateVerificationCode();
117	        LocalDateTime expiresAt = LocalDateTime.now().plusSeconds(VERIFICATION_CODE_EXPIRES_IN_SECONDS);
118	        verificationCodeRepository.save(new VerificationCode(request.getEmail(), code, REGISTER_CODE_TYPE, expiresAt));
119	
120	        emailService.sendVerificationCode(request.getEmail(), code, VERIFICATION_CODE_EXPIRES_IN_SECONDS);
121	        return new RegisterResponse(VERIFICATION_CODE_SENT, VERIFICATION_CODE_EXPIRES_IN_SECONDS);
122	    }
123	
124	    @Transactional
125	    public void verifyEmail(VerifyEmailRequest request) {
126	        // A valid one-time registration code is the only path that unlocks a new
127	        // account.
128	        VerificationCode verificationCode = verificationCodeRepository
129	                .findByEmailAndCodeAndType(request.getEmail(), request.getCode(), REGISTER_CODE_TYPE)
130	                .orElseThrow(() -> new BadRequestException(VERIFICATION_CODE_NOT_FOUND));
131	
132	        validateVerificationCode(verificationCode);
133	
134	        User user = userRepository.findByEmail(request.getEmail())
135	                .orElseThrow(() -> new ResourceNotFoundException(USER_NOT_FOUND));
136	
137	        verificationCode.setUsed(true);
138	        verificationCodeRepository.save(verificationCode);
139	
140	        user.setIsLocked(false);
141	        user.setLockUntil(null);
142	        user.setFailedLoginAttempts(0);
143	        userRepository.save(user);
144	
145	        logger.info("Email verified and account enabled: {}", request.getEmail());
146	    }
147	
148	    @Transactional(noRollbackFor = UnauthorizedException.class)
149	    public LoginResponse login(LoginRequest request) {
150	        // Spring Security performs the password check; this service records lockout
151	        // state
152	        // around that check and creates the stateless session tokens after success.
153	        User user = userRepository.findByUsername(request.getUsername())
154	                .orElseThrow(() -> new UnauthorizedException(BAD_CREDENTIALS));
155	
156	        ensureUserCanAttemptLogin(user);
157	
158	        try {
159	            authenticationManager.authenticate(
160	                    new UsernamePasswordAuthenticationToken(request.getUsername(), request.getPassword()));
161	        } catch (AuthenticationException e) {
162	            boolean locked = recordFailedLogin(user);
163	            if (locked) {
164	                throw new UnauthorizedException(ACCOUNT_LOCKED_PREFIX + lockDurationSeconds + " second(s)");
165	            }
166	            throw new UnauthorizedException(BAD_CREDENTIALS);
167	        }
168	
169	        resetFailedLoginState(user);
170	
171	        String accessToken = jwtUtil.generateToken(user.getUsername());
172	        RefreshToken refreshToken = createRefreshToken(user.getId());
173	
174	        logger.info("User logged in: {}", user.getUsername());
175	        return new LoginResponse(
176	                accessToken,
177	                refreshToken.getToken(),
178	                jwtUtil.getExpiration(),
179	                user.getUsername(),
180	                user.getEmail(),
181	                user.getRole());
182	    }
