184	    private void ensureUserCanAttemptLogin(User user) {
185	        // isLocked with null lockUntil means "email not verified"; with a future
186	        // lockUntil
187	        // means temporary lock caused by repeated failed login attempts.
188	        if (!Boolean.TRUE.equals(user.getIsLocked())) {
189	            return;
190	        }
191	
192	        if (user.getLockUntil() == null) {
193	            throw new UnauthorizedException(EMAIL_NOT_VERIFIED);
194	        }
195	
196	        if (LocalDateTime.now().isBefore(user.getLockUntil())) {
197	            long remainingSeconds = Duration.between(LocalDateTime.now(), user.getLockUntil()).toSeconds();
198	            throw new UnauthorizedException(ACCOUNT_LOCKED_PREFIX + Math.max(1, remainingSeconds) + " second(s)");
199	        }
200	
201	        user.setIsLocked(false);
202	        user.setLockUntil(null);
203	        user.setFailedLoginAttempts(0);
204	        userRepository.save(user);
205	    }
206	
207	    private boolean recordFailedLogin(User user) {
208	        // Failed attempts are stored on the user record so protection survives restarts
209	        // and applies consistently across all application instances.
210	        int attempts = user.getFailedLoginAttempts() == null ? 1 : user.getFailedLoginAttempts() + 1;
211	        user.setFailedLoginAttempts(attempts);
212	
213	        boolean locked = false;
214	        if (attempts >= maxFailedAttempts) {
215	            user.setIsLocked(true);
216	            user.setLockUntil(LocalDateTime.now().plusSeconds(lockDurationSeconds));
217	            locked = true;
218	            logger.warn("Account locked after failed login attempts: username={}, attempts={}", user.getUsername(),
219	                    attempts);
220	        }
221	
222	        userRepository.save(user);
223	        logger.warn("Login failed: username={}, attempts={}", user.getUsername(), attempts);
224	        return locked;
225	    }
226	
227	    private void resetFailedLoginState(User user) {
228	        if (user.getFailedLoginAttempts() == null || user.getFailedLoginAttempts() == 0) {
229	            return;
230	        }
231	
232	        user.setFailedLoginAttempts(0);
233	        user.setIsLocked(false);
234	        user.setLockUntil(null);
235	        userRepository.save(user);
236	    }
237	
238	    private String generateVerificationCode() {
239	        int code = 100000 + secureRandom.nextInt(900000);
240	        return String.valueOf(code);
241	    }
