243	    @Transactional
244	    public RefreshToken createRefreshToken(Long userId) {
245	        RefreshToken refreshToken = new RefreshToken(
246	                userId,
247	                UUID.randomUUID().toString(),
248	                LocalDateTime.now().plusSeconds(refreshExpiration / 1000));
249	        return refreshTokenRepository.save(refreshToken);
250	    }
251	
252	    @Transactional
253	    public RefreshTokenResponse refreshToken(RefreshTokenRequest request) {
254	        // Refresh tokens are rotated on every use. The old token is revoked before a
255	        // new
256	        // token pair is returned, reducing the value of a leaked refresh token.
257	        RefreshToken refreshToken = refreshTokenRepository.findByToken(request.getRefreshToken())
258	                .orElseThrow(() -> new UnauthorizedException(REFRESH_TOKEN_INVALID));
259	
260	        if (!refreshToken.isValid()) {
261	            throw new UnauthorizedException(REFRESH_TOKEN_EXPIRED_OR_REVOKED);
262	        }
263	
264	        User user = userRepository.findById(refreshToken.getUserId())
265	                .orElseThrow(() -> new ResourceNotFoundException(USER_NOT_FOUND));
266	        if (Boolean.TRUE.equals(user.getIsLocked())) {
267	            throw new UnauthorizedException(ACCOUNT_UNAVAILABLE);
268	        }
269	
270	        refreshToken.setRevoked(true);
271	        refreshTokenRepository.save(refreshToken);
272	
273	        String newAccessToken = jwtUtil.generateToken(user.getUsername());
274	        RefreshToken newRefreshToken = createRefreshToken(user.getId());
275	
276	        logger.info("Token refreshed: {}", user.getUsername());
277	        return new RefreshTokenResponse(newAccessToken, newRefreshToken.getToken(), jwtUtil.getExpiration());
278	    }
279	
280	    @Transactional
281	    public void logout(String refreshToken) {
282	        // Logout only needs the refresh token because access tokens are short-lived
283	        // JWTs
284	        // and are not stored server-side.
285	        RefreshToken token = refreshTokenRepository.findByToken(refreshToken)
286	                .orElseThrow(() -> new UnauthorizedException(REFRESH_TOKEN_INVALID));
287	
288	        token.setRevoked(true);
289	        refreshTokenRepository.save(token);
290	
291	        logger.info("User logged out: userId={}", token.getUserId());
292	    }
293	
294	    @Transactional
295	    public void revokeAllUserTokens(Long userId) {
296	        List<RefreshToken> tokens = refreshTokenRepository.findByUserIdAndRevokedFalse(userId);
297	        tokens.forEach(token -> token.setRevoked(true));
298	        refreshTokenRepository.saveAll(tokens);
299	        logger.info("Revoked all refresh tokens for userId={}", userId);
300	    }
301	
302	    @Transactional
303	    public void forgotPassword(String email) {
304	        // Return the same public response whether the email exists or not to avoid
305	        // leaking which addresses are registered.
306	        if (!userRepository.existsByEmail(email)) {
307	            logger.warn("Password reset requested for unknown email: {}", email);
308	            return;
309	        }
310	
311	        String code = generateVerificationCode();
312	        LocalDateTime expiresAt = LocalDateTime.now().plusSeconds(VERIFICATION_CODE_EXPIRES_IN_SECONDS);
313	        verificationCodeRepository.save(new VerificationCode(email, code, PASSWORD_RESET_CODE_TYPE, expiresAt));
314	
315	        emailService.sendPasswordResetCode(email, code, VERIFICATION_CODE_EXPIRES_IN_SECONDS);
316	    }
317	
318	    @Transactional
319	    public void resetPassword(String email, String code, String newPassword) {
320	        // Password reset consumes a dedicated verification code and revokes existing
321	        // sessions so old refresh tokens cannot survive a credential change.
322	        VerificationCode verificationCode = verificationCodeRepository
323	                .findByEmailAndCode(email, code)
324	                .orElseThrow(() -> new BadRequestException(VERIFICATION_CODE_NOT_FOUND));
325	
326	        validateVerificationCode(verificationCode);
327	        if (!PASSWORD_RESET_CODE_TYPE.equals(verificationCode.getType())) {
328	            throw new BadRequestException(VERIFICATION_CODE_TYPE_INVALID);
329	        }
330	
331	        User user = userRepository.findByEmail(email)
332	                .orElseThrow(() -> new ResourceNotFoundException(USER_NOT_FOUND));
333	
334	        user.setPasswordHash(passwordEncoder.encode(newPassword));
335	        user.setFailedLoginAttempts(0);
336	        user.setIsLocked(false);
337	        user.setLockUntil(null);
338	        userRepository.save(user);
339	
340	        verificationCode.setUsed(true);
341	        verificationCodeRepository.save(verificationCode);
342	
343	        revokeAllUserTokens(user.getId());
344	        logger.info("Password reset completed: {}", email);
345	    }
346	
347	    private void validateVerificationCode(VerificationCode verificationCode) {
348	        if (verificationCode.getUsed()) {
349	            throw new BadRequestException(VERIFICATION_CODE_USED);
350	        }
351	        if (verificationCode.isExpired()) {
352	            throw new BadRequestException(VERIFICATION_CODE_EXPIRED);
353	        }
354	    }
355	}
